#[path = "../src/legacy_session.rs"]
mod legacy_session;

use legacy_session::{SessionError, SessionState};
use std::path::PathBuf;

#[test]
#[ignore = "requires a disposable session generated by the legacy Python writer"]
fn reads_python_session_fixture() {
    let home = PathBuf::from(std::env::var_os("MG_LEGACY_FIXTURE_HOME").expect("fixture home"));
    let now = 1_999_999_999;
    #[cfg(windows)]
    let session = legacy_session::load_current_user(&home, now);
    #[cfg(not(windows))]
    let session = legacy_session::load_with(&home, now, |ciphertext| {
        let payload = ciphertext
            .strip_prefix(b"test-v1:")
            .ok_or(SessionError::Invalid)?;
        Ok(zeroize::Zeroizing::new(
            payload.iter().rev().copied().collect(),
        ))
    });
    let state = match session {
        Ok(SessionState::Ready(session)) => {
            assert!(session.account() == format!("client-{}", "a".repeat(32)));
            assert!(session.bearer() == format!("mgr_{}_{}", "b".repeat(24), "C".repeat(43)));
            "ready"
        }
        Ok(SessionState::Expired) => "expired",
        Ok(SessionState::Missing) => "missing",
        Err(SessionError::Invalid) => "invalid",
        Err(SessionError::Unavailable) => "unavailable",
    };
    println!("LEGACY_SESSION:{state}");
}
